modify_existing.before:
it.each([0, undefined, null])(
    `[AC-B1-08e-TIME#2] ${source} 时间 %s 统一为 null，保留原秒字段含义`,
    async (absent) => {
      const input = sourceRow(source);
      for (const key of [
        'order_pay_time',
        'order_receive_time',
        'order_settle_time',
        'order_modify_at',
      ]) {
        if (absent === undefined) delete input[key];
        else input[key] = absent;
      }
      const dto = await one(source, input);
      expect(dto).toMatchObject({
        deposit_paid_at: null,
        paid_at: null,
        received_at: null,
        settled_at: null,
        modified_at: null,
        order_pay_time: absent === 0 ? 0 : null,
        order_modify_at: absent === 0 ? 0 : null,
        order_receive_time: source === 'increment' && absent === 0 ? 0 : null,
        order_settle_time: source !== 'detail' && absent === 0 ? 0 : null,
      });
    },
  );

